var i=`0017-sichenyky`;var o=`world-0017`;var t=`UA`;var a=`eastern-europe`;var s=4;var l=27;var r={en:`Sichenyky`,ua:`Січеники`};var d={en:`A classic dish from Ukraine, featuring ground pork, yellow onion, chicken egg, garlic. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: свинячий фарш, жовта цибуля, куряче яйце, часник. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-pork`,450,`g`],[`yellow-onion`,130,`g`],[`chicken-egg`,1,`pcs`],[`garlic`,2,`clove`],[`white-bread`,90,`g`],[`whole-cow-milk`,100,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`sunflower-oil`,40,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:2,i:[[`dill`,12,`g`]]}];var u={slug:i,id:o,country:`UA`,region:a,servings:4,minutes:27,title:r,text:d,steps:g};export{t as country,u as default,o as id,l as minutes,a as region,s as servings,i as slug,g as steps,d as text,r as title};